ALTER TABLE tantu.collections ADD UNIQUE(workspace_id,record_id);
CREATE TABLE tantu.knowledge_templates(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,user_id uuid NOT NULL,source_id uuid NOT NULL,name text NOT NULL CHECK(length(name) BETWEEN 1 AND 100),include_rows boolean NOT NULL,source_fingerprint text NOT NULL,version integer NOT NULL DEFAULT 1,UNIQUE(workspace_id,user_id,name),FOREIGN KEY(workspace_id,source_id) REFERENCES tantu.collections(workspace_id,record_id));
CREATE TABLE tantu.template_reviews(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,user_id uuid NOT NULL,template_id uuid NOT NULL REFERENCES tantu.knowledge_templates,template_version integer NOT NULL,fingerprint text NOT NULL,expires_at timestamptz NOT NULL DEFAULT now()+interval '10 minutes');
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['knowledge_templates','template_reviews'] LOOP EXECUTE format('ALTER TABLE tantu.%I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('ALTER TABLE tantu.%I FORCE ROW LEVEL SECURITY',t); EXECUTE format('CREATE POLICY template_scope ON tantu.%I FOR ALL USING(workspace_id=tantu.tenant() AND user_id=tantu.actor() AND tantu.member_role(workspace_id) IS NOT NULL) WITH CHECK(workspace_id=tantu.tenant() AND user_id=tantu.actor() AND tantu.member_role(workspace_id) IS NOT NULL)',t); END LOOP; END $$;
CREATE TABLE tantu.knowledge_embeds(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,record_id uuid NOT NULL,target_id uuid NOT NULL,CHECK(record_id<>target_id),UNIQUE(record_id,target_id),FOREIGN KEY(workspace_id,record_id) REFERENCES tantu.records(workspace_id,id),FOREIGN KEY(workspace_id,target_id) REFERENCES tantu.records(workspace_id,id));
ALTER TABLE tantu.knowledge_embeds ENABLE ROW LEVEL SECURITY;
ALTER TABLE tantu.knowledge_embeds FORCE ROW LEVEL SECURITY;
CREATE POLICY embed_read ON tantu.knowledge_embeds FOR SELECT USING(workspace_id=tantu.tenant() AND tantu.can_access(record_id));
CREATE POLICY embed_insert ON tantu.knowledge_embeds FOR INSERT WITH CHECK(workspace_id=tantu.tenant() AND tantu.can_access(record_id,true) AND tantu.can_access(target_id));
CREATE POLICY embed_delete ON tantu.knowledge_embeds FOR DELETE USING(workspace_id=tantu.tenant() AND tantu.can_access(record_id,true));
